/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var Float64Array = require( '@stdlib/array/float64' );
var winograd = require( './../lib/winograd.js' );
var dgemmsw = require( './../lib/dgemmsw.js' );


// FIXTURES //

var cntantb = require( './fixtures/column_major_nta_ntb.json' );
var ctantb = require( './fixtures/column_major_ta_ntb.json' );
var cntatb = require( './fixtures/column_major_nta_tb.json' );
var ctatb = require( './fixtures/column_major_ta_tb.json' );
var rntantb = require( './fixtures/row_major_nta_ntb.json' );
var rtantb = require( './fixtures/row_major_ta_ntb.json' );
var rntatb = require( './fixtures/row_major_nta_tb.json' );
var rtatb = require( './fixtures/row_major_ta_tb.json' );
var rntantbAlpha2Beta3 = require( './fixtures/row_major_nta_ntb_alpha2_beta3.json' );


// FUNCTIONS //

/**
* Returns an implementation which uses a recursion cutoff equal to one, thus forcing the Strassen–Winograd algorithm for the fixture problem sizes, along with a counter of Strassen–Winograd kernel invocations.
*
* ## Notes
*
* -   Stubs are applied to the modules which directly require the stubbed modules (`./defaults.js` and `./base.js` are required by `./dgemmsw.js`, and `./winograd.js` is required by `./base.js`).
* -   If a stub fails to apply, the kernel is never invoked, and the invocation count remains zero.
*
* @private
* @returns {Object} object containing the implementation (`dgemmsw`) and the number of kernel invocations (`count`)
*/
function recursive() {
	var base;
	var out;

	out = {
		'dgemmsw': null,
		'count': 0
	};
	base = proxyquire( './../lib/base.js', {
		'./winograd.js': counter
	});
	out.dgemmsw = proxyquire( './../lib/dgemmsw.js', {
		'./defaults.js': {
			'CUTOFF': 1,
			'LEVELS': 100
		},
		'./base.js': base
	});
	return out;

	/**
	* Invokes the Strassen–Winograd kernel and increments the invocation count.
	*
	* @private
	* @returns {Float64Array} output matrix
	*/
	function counter() {
		out.count += 1;
		return winograd.apply( null, arguments );
	}
}

/**
* Performs the matrix-matrix operation described by a fixture using the default implementation and an implementation which forces recursion, and asserts that both implementations return the expected results.
*
* @private
* @param {Object} t - test object
* @param {Object} data - fixture data
*/
function check( t, data ) {
	var expected;
	var impl;
	var out;
	var a;
	var b;
	var c;

	expected = new Float64Array( data.C_out );

	// Default implementation (the fixture problem sizes are less than the default recursion cutoff, so the computation is delegated to `dgemm`)...
	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	out = dgemmsw( data.order, data.transA, data.transB, data.M, data.N, data.K, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	// Forced recursion (one level of the Strassen–Winograd recursion, followed by dynamic peeling of the odd inner dimension)...
	impl = recursive();

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	out = impl.dgemmsw( data.order, data.transA, data.transB, data.M, data.N, data.K, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.deepEqual( a, new Float64Array( data.A ), 'does not mutate the first input matrix' );
	t.deepEqual( b, new Float64Array( data.B ), 'does not mutate the second input matrix' );
	t.strictEqual( impl.count > 0, true, 'invokes the Strassen–Winograd kernel' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgemmsw, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (row-major, no-transpose, no-transpose)', function test( t ) {
	check( t, rntantb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (column-major, no-transpose, no-transpose)', function test( t ) {
	check( t, cntantb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (row-major, transpose, no-transpose)', function test( t ) {
	check( t, rtantb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (column-major, transpose, no-transpose)', function test( t ) {
	check( t, ctantb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (row-major, no-transpose, transpose)', function test( t ) {
	check( t, rntatb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (column-major, no-transpose, transpose)', function test( t ) {
	check( t, cntatb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (row-major, transpose, transpose)', function test( t ) {
	check( t, rtatb );
	t.end();
});

tape( 'the function performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` (column-major, transpose, transpose)', function test( t ) {
	check( t, ctatb );
	t.end();
});

tape( 'the function correctly applies both `α` and `β` scalars (row-major, no-transpose, no-transpose, α=2, β=3)', function test( t ) {
	check( t, rntantbAlpha2Beta3 );
	t.end();
});
